<?php
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../config/cart_service.php';
require_once __DIR__.'/../config/checkout_payment.php';
require_once __DIR__.'/../config/customer_order_access.php';
require_once __DIR__.'/../config/maps.php';
$mapsConfig=hydromis_maps_config();
if(empty($_SESSION['cart_csrf']))$_SESSION['cart_csrf']=bin2hex(random_bytes(32));
$fieldErrors=[];$uploadedProof=null;$error='';$userId=(string)($_SESSION['customer_user_id']??'');$checkoutUserId='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!is_string($_POST['csrf_token']??null) || !hash_equals($_SESSION['cart_csrf'],$_POST['csrf_token'])){http_response_code(403);exit('Refresh the cart before continuing.');}
    try{
        if(($_POST['action']??'')==='place'){
            $clean=validate_cart_checkout($_POST,(string)($_SESSION['cart_fulfillment']??'delivery'));
            $matched=cart_customer_by_mobile($conn,$clean['mobile_number']);
            if(!$matched)throw new CartValidationException(['mobile_number'=>'This number is not registered. Create an account using the link below, then return to your saved cart.']);
            if(!in_array($matched['status'],['approved','pending'],true))throw new CartValidationException(['mobile_number'=>'This customer account is unavailable. Contact the station for assistance.']);
            $checkoutUserId=(string)$matched['user_id'];
            $wallet=checkout_wallet_submission($clean['payment_method'],$clean,$_FILES);
            $uploadedProof=$wallet['proof']??null;
            $id=place_cart_order($conn,$checkoutUserId,cart_items(),(string)($_SESSION['cart_fulfillment']??'delivery'),$clean['payment_method'],$clean['notes'],(float)$clean['expected_total'],['address'=>$clean['delivery_address'],'latitude'=>$clean['delivery_latitude'],'longitude'=>$clean['delivery_longitude']],$wallet);
            $_SESSION['hydromis_cart']=[];$_SESSION['cart_csrf']=bin2hex(random_bytes(32));
            $_SESSION['checkout_receipts'][$id]=$checkoutUserId;
            $destination='order_receipt.php?transaction_id='.urlencode($id);
            header('Location: '.$destination,true,303);exit;
        }elseif(($_POST['action']??'')==='fulfillment'){
            if(!in_array($_POST['fulfillment']??'', ['delivery','pickup'],true))throw new InvalidArgumentException('Choose delivery or pickup.');
            $_SESSION['cart_fulfillment']=$_POST['fulfillment'];
        }else cart_change($_POST);
        header('Location: cart.php',true,303);exit;
    }catch(Throwable $e){if($e instanceof CartValidationException)$fieldErrors=$e->fields;if($uploadedProof)hydromis_delete_object($uploadedProof);error_log('[Cart] '.$e->getMessage());$error=$e instanceof InvalidArgumentException||$e instanceof RuntimeException?$e->getMessage():'Unable to place your order. Your cart has been kept.';}
}
$fulfillment=(string)($_SESSION['cart_fulfillment']??'delivery');
$cup=cart_cup_product($conn);
$quote=cart_quote(cart_items(),system_container_prices($conn),system_refill_pricing_mode($conn),system_order_pricing_rules($conn),$fulfillment,$cup);
$freeDelivery=$fulfillment==='delivery' && cart_free_delivery_claim($conn,$checkoutUserId)!==null;
if($freeDelivery){$quote['total']=round($quote['total']-$quote['delivery'],2);$quote['delivery']=0;}
$paymentQr=[];$qrResult=$conn->query('SELECT payment_method,qr_image_path,account_number,account_name FROM payment_qr_settings');
if($qrResult)while($qr=$qrResult->fetch_assoc())$paymentQr[$qr['payment_method']]=$qr;
function cart_h($value){return htmlspecialchars(is_scalar($value)?(string)$value:'',ENT_QUOTES,'UTF-8');}
function cart_field_error($name){global $fieldErrors;return isset($fieldErrors[$name])?'<small class="field-error" id="error-'.cart_h($name).'">'.cart_h($fieldErrors[$name]).'</small>':'';}
function cart_money($value){return 'PHP '.number_format($value,2);}
?>
